import 'package:dio/dio.dart';import 'package:flutter_test/flutter_test.dart';import 'package:http_mock_adapter/http_mock_adapter.dart';import 'package:tmyv_deneg_web/core/api_exceptions.dart';import 'package:tmyv_deneg_web/repositories/api_book_repository.dart';import 'package:tmyv_deneg_web/models/book.dart';import 'package:tmyv_deneg_web/models/book_query.dart';import 'package:tmyv_deneg_web/repositories/repository_errors.dart';
void main(){late Dio dio;late DioAdapter mock;late ApiBookRepository repo;setUp((){dio=Dio(BaseOptions(baseUrl:'http://test/api',validateStatus:(s)=>s!=null&&s<500));mock=DioAdapter(dio:dio);dio.interceptors.add(InterceptorsWrapper(onResponse:(r,h){if((r.statusCode??0)>=400){h.reject(DioException(requestOptions:r.requestOptions,response:r,error:mapHttpError(r.statusCode!,r.data),type:DioExceptionType.badResponse),true);}else h.next(r);}));repo=ApiBookRepository(dio);});test('loads page',()async{mock.onGet('/books',(s)=>s.reply(200,{'items':[],'page':1,'size':10,'total':0}),queryParameters:{'sort':'title,asc','page':1,'size':10});final p=await repo.find(const BookQuery());expect(p.total,0);});test('creates book',()async{final b=Book(id:0,title:'X',isbn:'1-2-3-4-5-6-7-8-9-0',year:2026,pages:100,publisherId:1,authorIds:[1],genreIds:[1],copiesTotal:1,copiesAvailable:1);mock.onPost('/books',(s)=>s.reply(201,{...b.toJson(),'id':25}),data:{'title':b.title,'isbn':b.isbn,'year':b.year,'pages':b.pages,'publisherId':b.publisherId,'authorIds':b.authorIds,'genreIds':b.genreIds,'copiesTotal':b.copiesTotal,'copiesAvailable':b.copiesAvailable});expect((await repo.create(b)).id,25);});test('422 maps to field error',()async{final b=Book(id:0,title:'X',isbn:'dup',year:2026,pages:100,publisherId:1,authorIds:[1],genreIds:[1],copiesTotal:1,copiesAvailable:1);mock.onPost('/books',(s)=>s.reply(422,{'message':'Ошибка валидации','errors':{'isbn':'Дубликат ISBN'}}),data:{'title':b.title,'isbn':b.isbn,'year':b.year,'pages':b.pages,'publisherId':b.publisherId,'authorIds':b.authorIds,'genreIds':b.genreIds,'copiesTotal':b.copiesTotal,'copiesAvailable':b.copiesAvailable});expect(()=>repo.create(b),throwsA(isA<FieldValidationException>()));});test('409 maps to conflict',()async{mock.onPost('/books/5/issue',(s)=>s.reply(409,{'message':'Нет свободных экземпляров'}));expect(()=>repo.issue(5),throwsA(isA<RepositoryConflictException>()));});test('connection error maps to network',(){final e=DioException(requestOptions:RequestOptions(path:'/books'),type:DioExceptionType.connectionError);expect(mapDioError(e),isA<RepositoryNetworkException>());});}
